#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=7

TENANT_ID="cdf89f94-8c88-48fc-b11c-dd24af4380b4"
FUNCTION_APP="func-twopoint-website-api"
QUEUE_NAME="subscription_welcome"
UNSUBSCRIBE_URI="https://twopoint.dev/unsubscribe/"

banner "Welcome email: Azure setup"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Sign in to Azure"
say "The wizard uses the Azure CLI for each change. It asks before each change."
if az account show >/dev/null 2>&1 && az functionapp list --query "[0].name" -o tsv >/dev/null 2>&1; then
  note "You are already signed in as $(az account show --query user.name -o tsv)."
else
  step "A browser window opens for the Azure sign-in."
  pause "Press Enter to start the sign-in."
  az login --tenant "$TENANT_ID" >/dev/null
fi
note "Subscription: $(az account show --query name -o tsv)"
pause

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Find the function app and its identity"
APP_RG=$(az functionapp list --query "[?name=='$FUNCTION_APP'].resourceGroup | [0]" -o tsv)
[[ -n "$APP_RG" ]] || { warn "Cannot find $FUNCTION_APP in this subscription."; exit 1; }
step "Function app: $FUNCTION_APP (resource group $APP_RG)"

app_setting() {
  az functionapp config appsettings list -n "$FUNCTION_APP" -g "$APP_RG" \
    --query "[?name=='Azure__$1' || name=='Azure:$1'].value | [0]" -o tsv
}

IDENTITY_CLIENT_ID=$(app_setting ManagedIdentityClientId)
IDENTITY_PRINCIPAL_ID=""
if [[ -n "$IDENTITY_CLIENT_ID" ]]; then
  IDENTITY_PRINCIPAL_ID=$(az identity list --query "[?clientId=='$IDENTITY_CLIENT_ID'].principalId | [0]" -o tsv)
fi
if [[ -z "$IDENTITY_PRINCIPAL_ID" ]]; then
  warn "Cannot find the managed identity from the Azure__ManagedIdentityClientId app setting."
  open_url "https://portal.azure.com/#view/HubsExtension/BrowseResource/resourceType/Microsoft.ManagedIdentity%2FuserAssignedIdentities"
  step "Open the identity that $FUNCTION_APP uses, then copy its Object (principal) ID."
  ask IDENTITY_PRINCIPAL_ID "Paste the principal ID:"
fi
step "Managed identity principal: $IDENTITY_PRINCIPAL_ID"

SERVICE_BUS_URI=$(app_setting ServiceBusUri)
SB_NAMESPACE=$(printf '%s' "$SERVICE_BUS_URI" | sed -E 's#^https?://([^.]+)\..*#\1#')
SB_ID=$(az servicebus namespace list --query "[?name=='$SB_NAMESPACE'].id | [0]" -o tsv)
SB_RG=$(az servicebus namespace list --query "[?name=='$SB_NAMESPACE'].resourceGroup | [0]" -o tsv)
[[ -n "$SB_ID" ]] || { warn "Cannot find the Service Bus namespace '$SB_NAMESPACE'."; exit 1; }
step "Service Bus namespace: $SB_NAMESPACE (resource group $SB_RG)"
pause

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Create the $QUEUE_NAME queue"
say "Subscribe puts one message on this queue for each welcome."
if az servicebus queue show -g "$SB_RG" --namespace-name "$SB_NAMESPACE" -n "$QUEUE_NAME" >/dev/null 2>&1; then
  note "The queue already exists. Nothing to do."
elif confirm "Create the queue '$QUEUE_NAME' in '$SB_NAMESPACE'?"; then
  az servicebus queue create -g "$SB_RG" --namespace-name "$SB_NAMESPACE" -n "$QUEUE_NAME" >/dev/null
  printf '  %s✓ created%s queue %s\n' "$GREEN" "$RESET" "$QUEUE_NAME"
else
  SKIPPED+=("Create the Service Bus queue $QUEUE_NAME in $SB_NAMESPACE")
fi
pause

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Let the identity send to Service Bus"
say "Subscribe sends the message with the managed identity."
SENDER_ROLES=$(az role assignment list --assignee "$IDENTITY_PRINCIPAL_ID" --scope "$SB_ID" --include-inherited \
  --query "[?roleDefinitionName=='Azure Service Bus Data Sender' || roleDefinitionName=='Azure Service Bus Data Owner'] | length(@)" -o tsv)
if [[ "${SENDER_ROLES:-0}" -gt 0 ]]; then
  note "The identity can already send to $SB_NAMESPACE. Nothing to do."
elif confirm "Give the identity 'Azure Service Bus Data Sender' on $SB_NAMESPACE?"; then
  az role assignment create --assignee-object-id "$IDENTITY_PRINCIPAL_ID" --assignee-principal-type ServicePrincipal \
    --role "Azure Service Bus Data Sender" --scope "$SB_ID" >/dev/null
  printf '  %s✓ assigned%s Azure Service Bus Data Sender\n' "$GREEN" "$RESET"
else
  SKIPPED+=("Assign Azure Service Bus Data Sender on $SB_NAMESPACE to $IDENTITY_PRINCIPAL_ID")
fi
pause

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Let the identity read newsletters"
say "The prod frontend deploy uploads each newsletter to blob storage."
say "It uses the GitHub secrets AZURE_STORAGE_ACCOUNT_NAME and AZURE_STORAGE_CONTAINER_NAME."
note "Storage accounts in this subscription: $(az storage account list --query "[].name" -o tsv | tr '\n' ' ')"
ask STORAGE_ACCOUNT "Storage account name (value of AZURE_STORAGE_ACCOUNT_NAME):"
ask NEWSLETTER_CONTAINER "Container name (Enter for 'newsletter'):"
NEWSLETTER_CONTAINER="${NEWSLETTER_CONTAINER:-newsletter}"
STORAGE_ID=$(az storage account show -n "$STORAGE_ACCOUNT" --query id -o tsv)
CONTAINER_SCOPE="$STORAGE_ID/blobServices/default/containers/$NEWSLETTER_CONTAINER"
READER_ROLES=$(az role assignment list --assignee "$IDENTITY_PRINCIPAL_ID" --scope "$CONTAINER_SCOPE" --include-inherited \
  --query "[?starts_with(roleDefinitionName, 'Storage Blob Data')] | length(@)" -o tsv)
if [[ "${READER_ROLES:-0}" -gt 0 ]]; then
  note "The identity can already read $NEWSLETTER_CONTAINER. Nothing to do."
elif confirm "Give the identity 'Storage Blob Data Reader' on the container '$NEWSLETTER_CONTAINER'?"; then
  az role assignment create --assignee-object-id "$IDENTITY_PRINCIPAL_ID" --assignee-principal-type ServicePrincipal \
    --role "Storage Blob Data Reader" --scope "$CONTAINER_SCOPE" >/dev/null
  printf '  %s✓ assigned%s Storage Blob Data Reader\n' "$GREEN" "$RESET"
else
  SKIPPED+=("Assign Storage Blob Data Reader on $STORAGE_ACCOUNT/$NEWSLETTER_CONTAINER to $IDENTITY_PRINCIPAL_ID")
fi
NEWSLETTER_CONTAINER_URI="https://$STORAGE_ACCOUNT.blob.core.windows.net/$NEWSLETTER_CONTAINER"
pause

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Add the Welcome app settings"
step "Welcome__NewsletterContainerUri = $NEWSLETTER_CONTAINER_URI"
step "Welcome__UnsubscribeUri = $UNSUBSCRIBE_URI"
step "Welcome__Enabled = false"
note "The function app restarts when its settings change."
if confirm "Write these settings to $FUNCTION_APP?"; then
  az functionapp config appsettings set -n "$FUNCTION_APP" -g "$APP_RG" --settings \
    "Welcome__NewsletterContainerUri=$NEWSLETTER_CONTAINER_URI" \
    "Welcome__UnsubscribeUri=$UNSUBSCRIBE_URI" \
    "Welcome__Enabled=false" >/dev/null
  printf '  %s✓ set%s the Welcome app settings\n' "$GREEN" "$RESET"
else
  SKIPPED+=("Set the Welcome__* app settings on $FUNCTION_APP")
fi
pause

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Turn on welcomes"
say "Turn on welcomes only after these two events:"
step "The backend with the welcome code is deployed (merge to staging main)."
step "A prod frontend release has uploaded newsletters with the new slots."
DEPLOYED_FUNCTIONS=$(az functionapp function list -n "$FUNCTION_APP" -g "$APP_RG" --query "[].name" -o tsv 2>/dev/null || true)
if [[ "$DEPLOYED_FUNCTIONS" == *"Queues-ProcessWelcomeMessage"* ]]; then
  note "✓ The deployed backend has the welcome queue function."
else
  warn "The deployed backend does not have the welcome queue function yet."
fi
LATEST_SLUG=$(curl -fsS https://twopoint.dev/rss.xml 2>/dev/null \
  | grep -o '<link>https://twopoint.dev/[^<]*</link>' | sed -n '2p' \
  | sed -E 's#.*/([^/<]+)/?</link>#\1#' || true)
if [[ -n "$LATEST_SLUG" ]]; then
  BLOB_FILE=$(mktemp)
  if az storage blob download --auth-mode login --account-name "$STORAGE_ACCOUNT" -c "$NEWSLETTER_CONTAINER" \
      -n "posts/$LATEST_SLUG/index" -f "$BLOB_FILE" >/dev/null 2>&1; then
    if grep -q '%%TWOPOINT_UNSUBSCRIBE_URL%%' "$BLOB_FILE" && grep -q '%%TWOPOINT_INTRO%%' "$BLOB_FILE"; then
      note "✓ The newsletter of '$LATEST_SLUG' has both slots."
    else
      warn "The newsletter of '$LATEST_SLUG' does not have the slots yet. Release the frontend to prod first."
    fi
  else
    warn "Cannot read posts/$LATEST_SLUG/index. Your account needs a Storage Blob Data role to check it."
  fi
  rm -f "$BLOB_FILE"
else
  warn "Cannot find the latest post in https://twopoint.dev/rss.xml."
fi
if confirm "Turn on welcomes now (Welcome__Enabled=true)?"; then
  az functionapp config appsettings set -n "$FUNCTION_APP" -g "$APP_RG" --settings "Welcome__Enabled=true" >/dev/null
  printf '  %s✓ turned on%s welcomes\n' "$GREEN" "$RESET"
else
  SKIPPED+=("Turn on welcomes later: az functionapp config appsettings set -n $FUNCTION_APP -g $APP_RG --settings Welcome__Enabled=true")
fi
pause

finish
}

run_wizard "$@"; exit
